# =============================================================================
# Helpers
# =============================================================================

def _file_exists(filename: str) -> bool:
    return (_RAW_DIR / filename).exists()


def _all_files_exist(filenames: list[str]) -> bool:
    return all(_file_exists(f) for f in filenames)


def _processed_exists() -> bool:
    return (
        (_PROCESSED_DIR / "train.csv").exists()
        and (_PROCESSED_DIR / "val.csv").exists()
        and (_PROCESSED_DIR / "test.csv").exists()
    )


def _load_df(split: str):
    """Load a processed split CSV as a pandas DataFrame."""
    import pandas as pd
    path = _PROCESSED_DIR / f"{split}.csv"
    if not path.exists():
        raise FileNotFoundError(
            f"Processed split '{split}' not found at {path}. "
            "Run the preprocessing pipeline first."
        )
    df = pd.read_csv(path)
    if "label" in df.columns:
        df["label"] = df["label"].astype(int)
    return df


# =============================================================================
# Service functions
# =============================================================================

async def get_catalog() -> dict:
    """Return the full dataset catalog with live availability flags."""
    entries = []
    for entry in _CATALOG:
        is_downloaded = _all_files_exist(entry["expected_files"])
        is_processed  = _processed_exists() if is_downloaded else False
        entries.append({
            **entry,
            "is_downloaded": is_downloaded,
            "is_processed":  is_processed,
        })
    return {"datasets": entries, "total": len(entries)}


async def get_dataset_stats(name: str) -> dict:
    """Return dataset_stats.json for the processed dataset."""
    if not _STATS_JSON.exists():
        raise FileNotFoundError(
            "No processed dataset found. Run the preprocessing pipeline first."
        )

    with open(_STATS_JSON, encoding="utf-8") as f:
        stats = json.load(f)

    # Get timestamp from audit log
    last_processed = None
    if _AUDIT_LOG.exists():
        with open(_AUDIT_LOG, encoding="utf-8") as f:
            audit = json.load(f)
            last_processed = audit.get("completed_at")

    return {
        "dataset_name":   name,
        "total_rows":     stats.get("total_rows", 0),
        "splits":         stats.get("splits", {}),
        "deduplication":  stats.get("deduplication", {}),
        "leakage":        stats.get("leakage", {}),
        "last_processed": last_processed,
    }


async def get_analytics(name: str, split: str = "train") -> dict:
    """Compute full analytics for a processed split."""
    from ml.preprocessing.analytics import full_analytics

    df = _load_df(split)

    result = full_analytics(df, raw_df=None, top_words=30)
    result["dataset_name"] = name
    result["split"]        = split
    result["computed_at"]  = datetime.now(timezone.utc).isoformat()
    return result


async def get_samples(
    name:         str,
    split:        str = "train",
    n:            int = 10,
    label_filter: Optional[int] = None,
) -> dict:
    """Return a random sample of rows from a processed split."""
    from ml.preprocessing.analytics import sample_rows

    df = _load_df(split)
    total = len(df[df["label"] == label_filter]) if label_filter is not None else len(df)
    rows  = sample_rows(df, n=n, label=label_filter)

    return {
        "dataset_name":    name,
        "split":           split,
        "label_filter":    label_filter,
        "total_in_split":  total,
        "samples":         rows,
    }


async def get_audit_log() -> Optional[dict]:
    """Return the preprocessing audit log if it exists."""
    if not _AUDIT_LOG.exists():
        return None
    with open(_AUDIT_LOG, encoding="utf-8") as f:
        return json.load(f)


async def handle_upload(
    filename:    str,
    content:     bytes,
) -> dict:
    """
    Save an uploaded dataset file to ml/datasets/raw/.

    Does NOT modify any existing files.
    Does NOT run preprocessing automatically — user must trigger that separately.

    Returns
    -------
    DatasetUploadResponse-compatible dict.
    """
    import pandas as pd

    # Sanitise filename
    safe_name = Path(filename).name
    if not safe_name:
        raise ValueError("Invalid filename.")

    allowed_ext = {".csv", ".tsv", ".json", ".jsonl"}
    ext = Path(safe_name).suffix.lower()
    if ext not in allowed_ext:
        raise ValueError(
            f"Unsupported file type '{ext}'. "
            f"Allowed: {allowed_ext}"
        )

    dest = _RAW_DIR / safe_name
    _RAW_DIR.mkdir(parents=True, exist_ok=True)

    dest.write_bytes(content)
    logger.info("Uploaded dataset file: %s (%d bytes)", dest, len(content))

    # Quick inspection
    rows_detected = None
    columns:       list[str] = []
    detected_text_col  = None
    detected_label_col = None
    sample_labels:     dict = {}

    try:
        from ml.preprocessing.loader import describe_file
        info = describe_file(str(dest))
        columns             = info.get("columns", [])
        detected_text_col   = info.get("detected_text_col")
        detected_label_col  = info.get("detected_label_col")
        sample_labels       = info.get("sample_label_distribution", {})
        sample_rows         = info.get("sample_rows", 0)
        rows_detected       = sample_rows   # partial read
    except Exception as exc:
        logger.warning("Could not inspect uploaded file: %s", exc)

    return {
        "filename":          safe_name,
        "size_bytes":        len(content),
        "rows_detected":     rows_detected,
        "columns":           columns,
        "detected_text_col": detected_text_col,
        "detected_label_col":detected_label_col,
        "sample_labels":     sample_labels,
        "message":           f"File '{safe_name}' saved to ml/datasets/raw/.",
        "next_step": (
            f"python scripts/prepare_dataset.py --files ml/datasets/raw/{safe_name}"
        ),
    }


async def trigger_preprocessing(request: dict) -> dict:
    """
    Run the preprocessing pipeline synchronously (for small datasets).
    For large datasets this should be a background task — returns immediately
    with status="started" and runs in a thread.
    """
    import asyncio
    from concurrent.futures import ThreadPoolExecutor
    from ml.preprocessing.pipeline import run_pipeline

    files    = request.get("files", [])
    paths    = [_RAW_DIR / f for f in files]

    # Validate files exist
    missing = [str(p) for p in paths if not p.exists()]
    if missing:
        return {
            "status":  "error",
            "message": f"Files not found: {missing}",
            "train_rows": None, "val_rows": None, "test_rows": None,
            "audit_path": None,
        }

    cleaning_mode = request.get("cleaning_mode", "baseline")
    lemmatize     = request.get("lemmatize", False)
    test_size     = request.get("test_size", 0.10)
    val_size      = request.get("val_size", 0.10)
    force         = request.get("force", False)

    try:
        loop = asyncio.get_running_loop()
        with ThreadPoolExecutor() as pool:
            train_df, val_df, test_df, _ = await loop.run_in_executor(
                pool,
                lambda: run_pipeline(
                    paths=paths,
                    cleaning_mode=cleaning_mode,
                    lemmatize=lemmatize,
                    test_size=test_size,
                    val_size=val_size,
                    force=force,
                    verbose=False,
                ),
            )

        return {
            "status":     "completed",
            "message":    "Preprocessing pipeline completed successfully.",
            "train_rows": len(train_df),
            "val_rows":   len(val_df),
            "test_rows":  len(test_df),
            "audit_path": str(_AUDIT_LOG) if _AUDIT_LOG.exists() else None,
        }
    except Exception as exc:
        logger.error("Preprocessing pipeline failed: %s", exc, exc_info=True)
        return {
            "status":  "error",
            "message": str(exc),
            "train_rows": None, "val_rows": None, "test_rows": None,
            "audit_path": None,
        }


async def get_export_csv(split: str) -> bytes:
    """
    Return a processed split CSV as bytes for download.

    IMPORTANT: Only processed CSVs are exported — not raw dataset text.
    The processed CSV contains cleaned_text (preprocessed) and label (0/1).
    It does NOT contain the full original article text.
    """
    path = _PROCESSED_DIR / f"{split}.csv"
    if not path.exists():
        raise FileNotFoundError(
            f"Processed split '{split}' not found. "
            "Run the preprocessing pipeline first."
        )
    return path.read_bytes()
